{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would require each local board of education to provide free breakfast and lunch to students in its schools who qualify for free or reduced-price meals under rules established by law.",
      "rationale": "Conveys the local boards' obligation to provide both free meals, the eligible student population, and the governing eligibility rules."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Subject to available funding, the state would reimburse each local education agency for the cost of free meals served to students who qualify for reduced-price meals, after available federal funds have been applied.",
      "rationale": "Includes the state reimbursement obligation, funding condition, covered students and costs, and requirement to apply available federal funds first."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "The bill would also remove the phrase “regardless of its participation” from one subdivision of Tennessee Code Annotated § 49-6-2303",
      "rationale": "Identifies the deleted language and section but omits subdivision (5), which is needed to identify the amendment's precise target."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "The bill would also remove the phrase “regardless of its participation” from one subdivision of Tennessee Code Annotated § 49-6-2303 and delete another subdivision",
      "rationale": "Conveys deletion of a subdivision of § 49-6-2303 but omits subdivision (10), leaving the repeal's target unidentified."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "In § 49-2-114(a), it would replace wording based on receiving free or reduced-price school lunches with wording based on household income meeting the eligibility requirements for those meals under 42 U.S.C. § 1758.",
      "rationale": "Identifies the amended provision and accurately conveys the shift from receiving lunches to household-income eligibility under the specified federal standard."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The changes would take effect July 1, 2025, and apply beginning with the 2025–2026 school year.",
      "rationale": "States the effective date and conveys ongoing application starting with the specified school year."
    }
  ]
}
